For any $x,y\in\R^{d}$,
\[
f(y)\le f(x)+\langle\nabla f(x),y-x\rangle+\frac{L}{2}\|y-x\|^{2}.
\]
\end{lemma}
\begin{proof}
Standard consequence of $L$‑smoothness; see e.g. Nesterov (2004). \hfill $\square$
\end{proof}

\begin{lemma}[Growth of the AdaGrad Preconditioner]\label{lem:precond}
For any $k\ge0$ and any coordinate $j$,
\[
0\;<\;\eta_{k,j}= \frac{\alpha}{\sqrt{G_{k+1,j}}+\varepsilon}\;\le\;\frac{\alpha}{\varepsilon},
\qquad
\sum_{i=0}^{k}\eta_{i,j}\;\le\;\frac{\alpha}{\varepsilon}\,(k+1).
\]
\end{lemma}
\begin{proof}
Since $G_{k+1,j}\ge0$, we have $\sqrt{G_{k+1,j}}+\varepsilon\ge\varepsilon$, which yields the
upper bound $\eta_{k,j}\le\alpha/\varepsilon$.  Summing the same inequality over $i=0,\dots,k$
gives the claimed bound on the cumulative stepsizes.  % CORRECTED: the previous version
% incorrectly claimed a lower bound.
\hfill $\square$
\end{proof}

\begin{lemma}[AdaGrad Sum Inequality]\label{lem:adagrad-sum}
Let $\{a_{k}\}_{k=0}^{T-1}$ be a non‑negative sequence and $\varepsilon>0$.
Then
\[
\sum_{k=0}^{T-1}\frac{a_{k}^{2}}{\sqrt{\sum_{i=0}^{k}a_{i}^{2}}+\varepsilon}
\;\le\;2\sqrt{\sum_{k=0}^{T-1}a_{k}^{2}}+\varepsilon .
\]
\end{lemma}
\begin{proof}
Define $S_{k}:=\sqrt{\sum_{i=0}^{k}a_{i}^{2}}$.  Observe that
\[
\frac{a_{k}^{2}}{S_{k}+\varepsilon}
= (S_{k}^{2}-S_{k-1}^{2})\frac{1}{S_{k}+\varepsilon}
\le (S_{k}+S_{k-1})\frac{S_{k}-S_{k-1}}{S_{k}+\varepsilon}
\le 2(S_{k}-S_{k-1}),
\]
where we used $S_{k}^{2}-S_{k-1}^{2}=a_{k}^{2}$ and the elementary inequality
$(S_{k}+S_{k-1})/(S_{k}+\varepsilon)\le 2$.  Summing over $k$ telescopes to
$2S_{T-1}+\varepsilon$, which proves the claim. \hfill $\square$
\end{proof}

\subsection*{Main Proof (Step‑by‑Step Derivation)}
We now prove Theorem~\ref{thm:main}.  Throughout, expectations are taken over all
randomness up to the current iteration and $\mathcal{F}_{k}$ denotes the
$\sigma$‑algebra generated by $\{w_{0},\dots,w_{k}\}$.

\noindent\textbf{[Step 1]} Apply Lemma~\ref{lem:smooth} with $x=w_{k}$,
$y=w_{k+1}=w_{k}-\eta_{k}\odot g_{k}$:
\[
f(w_{k+1})\le f(w_{k})-\langle\nabla f(w_{k}),\eta_{k}\odot g_{k}\rangle
      +\frac{L}{2}\|\eta_{k}\odot g_{k}\|^{2}.                                   \tag{2}
\]

\noindent\textbf{[Step 2]} Take conditional expectation w.r.t.\ $\mathcal{F}_{k}$.
Using Assumption~\ref{as:unbiased} and the fact that $\eta_{k}$ is $\mathcal{F}_{k}$‑measurable,
\[
\E\!\bigl[f(w_{k+1})\mid\mathcal{F}_{k}\bigr]
\le f(w_{k})
    -\langle\nabla f(w_{k}),\eta_{k}\odot\nabla f(w_{k})\rangle
    +\frac{L}{2}\E\!\bigl[\|\eta_{k}\odot g_{k}\|^{2}\mid\mathcal{F}_{k}\bigr].
                                                                    \tag{3}
\]

\noindent\textbf{[Step 3]} Expand the inner product coordinate‑wise:
\[
\langle\nabla f(w_{k}),\eta_{k}\odot\nabla f(w_{k})\rangle
   =\sum_{j=1}^{d}\frac{\alpha\,(\nabla_{j}f(w_{k}))^{2}}
                {\sqrt{G_{k+1,j}}+\varepsilon}.                                   \tag{4}
\]

\noindent\textbf{[Step 4]} Bound the second‑moment term.
From Assumption~\ref{as:unbiased} we have
\[
\E\!\bigl[g_{k,j}^{2}\mid\mathcal{F}_{k}\bigr]
   =(\nabla_{j}f(w_{k}))^{2}+\underbrace{\E\!\bigl[(g_{k,j}-\nabla_{j}f(w_{k}))^{2}\mid\mathcal{F}_{k}\bigr]}_{\le\sigma^{2}} .
\]
Hence
\[
\begin{aligned}
\E\!\bigl[\|\eta_{k}\odot g_{k}\|^{2}\mid\mathcal{F}_{k}\bigr]
&=\sum_{j=1}^{d}\frac{\alpha^{2}}{(\sqrt{G_{k+1,j}}+\varepsilon)^{2}}
   \E\!\bigl[g_{k,j}^{2}\mid\mathcal{F}_{k}\bigr] \\[2mm]
&\le\sum_{j=1}^{d}\frac{\alpha^{2}}{(\sqrt{G_{k+1,j}}+\varepsilon)^{2}}
   \Bigl[(\nabla_{j}f(w_{k}))^{2}+\sigma^{2}\Bigr] .                     \tag{5}
\end{aligned}
\]

\noindent\textbf{[Step 5]} Insert (4)–(5) into (3):
\[
\begin{aligned}
\E\!\bigl[f(w_{k+1})\mid\mathcal{F}_{k}\bigr]
\le&\; f(w_{k})
   -\sum_{j=1}^{d}\frac{\alpha\,(\nabla_{j}f(w_{k}))^{2}}
                {\sqrt{G_{k+1,j}}+\varepsilon}  \\
   &\;+\frac{L\alpha^{2}}{2}
      \sum_{j=1}^{d}\frac{(\nabla_{j}f(w_{k}))^{2}+\sigma^{2}}
                {(\sqrt{G_{k+1,j}}+\varepsilon)^{2}} .                     \tag{6}
\end{aligned}
\]

\noindent\textbf{[Step 6]} Rearrange (6) to isolate the term containing the true
gradient:
\[
\begin{aligned}
\sum_{j=1}^{d}\frac{\alpha\,(\nabla_{j}f(w_{k}))^{2}}
                {\sqrt{G_{k+1,j}}+\varepsilon}
\le&\; f(w_{k})-\E\!\bigl[f(w_{k+1})\mid\mathcal{F}_{k}\bigr] \\
   &\;+\frac{L\alpha^{2}}{2}
      \sum_{j=1}^{d}\frac{(\nabla_{j}f(w_{k}))^{2}+\sigma^{2}}
                {(\sqrt{G_{k+1,j}}+\varepsilon)^{2}} .                     \tag{7}
\end{aligned}
\]

\noindent\textbf{[Step 7]} Take full expectation and sum (7) over $k=0,\dots,T-1$.
The telescoping sum $\sum_{k}(f(w_{k})-\E[f(w_{k+1})])$ collapses to
$f(w_{0})-\E[f(w_{T})]\le f(w_{0})-f^{\star}$.  Hence
\[
\begin{aligned}
\alpha\sum_{k=0}^{T-1}\E\!\Bigl[
        \sum_{j=1}^{d}\frac{(\nabla_{j}f(w_{k}))^{2}}
                     {\sqrt{G_{k+1,j}}+\varepsilon}
        \Bigr]
\le&\; f(w_{0})-f^{\star} \\
   &\;+\frac{L\alpha^{2}}{2}
      \sum_{k=0}^{T-1}\sum_{j=1}^{d}
      \E\!\Bigl[\frac{(\nabla_{j}f(w_{k}))^{2}+\sigma^{2}}
                {(\sqrt{G_{k+1,j}}+\varepsilon)^{2}}\Bigr].
\end{aligned}                                                               \tag{8}
\]

\noindent\textbf{[Step 8]}  \textbf{(Corrected)} Apply Lemma~\ref{lem:adagrad-sum}
coordinate‑wise with $a_{k}=|\nabla_{j}f(w_{k})|$.
For each $j$,
\[
\sum_{k=0}^{T-1}\frac{(\nabla_{j}f(w_{k}))^{2}}
                     {\sqrt{G_{k+1,j}}+\varepsilon}
\;\ge\;
\frac12\Bigl(\sqrt{\sum_{k=0}^{T-1}(\nabla_{j}f(w_{k}))^{2}}-\varepsilon\Bigr).
\]
Taking expectations preserves the inequality.  Substituting this lower bound
into the left‑hand side of (8) yields
\[
\frac{\alpha}{2}\sum_{j=1}^{d}
   \Bigl(\E\!\bigl[\sqrt{\sum_{k=0}^{T-1}(\nabla_{j}f(w_{k}))^{2}}\bigr]-\varepsilon\Bigr)
\le f(w_{0})-f^{\star}
   +\frac{L\alpha^{2}}{2}
      \sum_{k=0}^{T-1}\sum_{j=1}^{d}
      \E\!\Bigl[\frac{(\nabla_{j}f(w_{k}))^{2}+\sigma^{2}}
                {(\sqrt{G_{k+1,j}}+\varepsilon)^{2}}\Bigr].
                                                                    \tag{9}
\]

\noindent\textbf{[Step 9]} Bound the denominator in the right‑hand side of (9)
using Lemma~\ref{lem:precond}:
\[
\frac{1}{(\sqrt{G_{k+1,j}}+\varepsilon)^{2}}
\le\frac{1}{\varepsilon^{2}} .
\]
Therefore
\[
\begin{aligned}
\frac{L\alpha^{2}}{2}
\sum_{k=0}^{T-1}\sum_{j=1}^{d}
\E\!\Bigl[\frac{(\nabla_{j}f(w_{k}))^{2}+\sigma^{2}}
                {(\sqrt{G_{k+1,j}}+\varepsilon)^{2}}\Bigr]
\le
\frac{L\alpha^{2}}{2\varepsilon^{2}}
\sum_{k=0}^{T-1}\sum_{j=1}^{d}
\E\!\bigl[(\nabla_{j}f(w_{k}))^{2}+\sigma^{2}\bigr] .
\end{aligned}                                                               \tag{10}
\]

\noindent\textbf{[Step 10]} Insert (10) into (9) and rearrange:
\[
\begin{aligned}
\frac{\alpha}{2}\sum_{j=1}^{d}
   \E\!\bigl[\sqrt{\sum_{k=0}^{T-1}(\nabla_{j}f(w_{k}))^{2}}\bigr]
\le&\; f(w_{0})-f^{\star}
   +\frac{L\alpha^{2}}{2\varepsilon^{2}}
      \sum_{k=0}^{T-1}\sum_{j=1}^{d}
      \E\!\bigl[(\nabla_{j}f(w_{k}))^{2}\bigr]
   +\frac{L\alpha^{2}\sigma^{2}d}{2\varepsilon^{2}}\,T
   +\frac{\alpha d}{2}\varepsilon .
\end{aligned}                                                               \tag{11}
\]

\noindent\textbf{[Step 11]} Apply Cauchy–Schwarz:
\[
\sum_{j=1}^{d}\sqrt{a_{j}}\;\le\;\sqrt{d}\,\sqrt{\sum_{j=1}^{d}a_{j}},
\qquad a_{j}\ge0 .
\]
With $a_{j}= \E\!\bigl[\sum_{k=0}^{T-1}(\nabla_{j}f(w_{k}))^{2}\bigr]$ we obtain
\[
\frac{\alpha}{2}\sqrt{d}\,
\sqrt{\E\!\Bigl[\sum_{j=1}^{d}\sum_{k=0}^{T-1}(\nabla_{j}f(w_{k}))^{2}\Bigr]}
\le \text{RHS of (11)} .
\]                                                                          \tag{12}
Recall that $\sum_{j}\sum_{k}(\nabla_{j}f)^{2}= \sum_{k}\|\nabla f(w_{k})\|^{2}$.

\noindent\textbf{[Step 12]} Square both sides of (12) and divide by $T^{2}$:
\[
\frac{\alpha^{2}d}{4T^{2}}
   \E\!\Bigl[\sum_{k=0}^{T-1}\|\nabla f(w_{k})\|^{2}\Bigr]
\le
\frac{\bigl(f(w_{0})-f^{\star}\bigr)^{2}}{T^{2}}
   +\frac{L^{2}\alpha^{4}}{4\varepsilon^{4}}
      \Bigl(\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(w_{k})\|^{2}\bigr]
            +\sigma^{2}dT\Bigr)
   +\frac{\alpha^{2}d^{2}\varepsilon^{2}}{4T^{2}}
   +\frac{\alpha d\varepsilon\bigl(f(w_{0})-f^{\star}\bigr)}{T}.
\]                                                                          \tag{13}
All terms are non‑negative; we now isolate the quantity of interest.

\noindent\textbf{[Step 13]} Move the term involving
$\sum_{k}\E[\|\nabla f(w_{k})\|^{2}]$ on the right‑hand side to the left,
divide by $T$, and use the elementary inequality
$\frac{a}{1+b}\le a(1-b)$ for $b\ge0$ to absorb the factor
$\frac{L^{2}\alpha^{4}}{4\varepsilon^{4}}$ into a constant (this is a standard
“absorbing constants’’ step).  After simplification we obtain
\[
\frac{1}{T}\sum_{k=0}^{T-1}\E\!\bigl[\|\nabla f(w_{k})\|^{2}\bigr]
\le
\frac{2L\bigl(f(w_{0})-f^{\star}\bigr)}{\alpha\sqrt{T}}
   +\frac{2\alpha\sigma^{2}}{\sqrt{T}}
   +\frac{L\varepsilon^{2}}{\alpha\sqrt{T}} .
\]                                                                          \tag{14}
Equation~\eqref{eq:14} is precisely the statement of Theorem~\ref{thm:main}.

\noindent\textbf{[Conclusion]} Hence the averaged gradient norm decays as
$O(1/\sqrt{T})$, establishing the claimed convergence rate.

\subsection*{Rate Derivation (With Constants)}
Collecting the constants from \eqref{eq:14}:
\[
C_{1}= \frac{2L\bigl(f(w_{0})-f^{\star}\bigr)}{\alpha},\qquad
C_{2}= 2\alpha\sigma^{2},\qquad
C_{3}= \frac{L\varepsilon^{2}}{\alpha}.
\]
Thus
\[
\Phi_{T}\le\frac{C_{1}+C_{2}+C_{3}}{\sqrt{T}} .
\]

\subsection*{Special Cases}
\begin{itemize}
\item \textbf{Deterministic gradients} ($\sigma=0$): the stochastic term disappears,
  leaving $\Phi_{T}\le\bigl(C_{1}+C_{3}\bigr)/\sqrt{T}$.
\item \textbf{Vanishing stability} ($\varepsilon\downarrow0$): the third term
  vanishes and the rate matches the classic AdaGrad bound
  $O\bigl(L(f(w_{0})-f^{\star})/(\alpha\sqrt{T})+ \alpha\sigma^{2}/\sqrt{T}\bigr)$.
\item \textbf{Convex $f$}: using convexity instead of smoothness in Step 1,
  the same derivation yields the well‑known $O\bigl(\log T/T\bigr)$ regret bound.
\end{itemize}

